<svelte:options runes={false} />
<script>
  import Popover from '$lib/components/popover.svelte';
  export let data={};
  const blank=()=>({id:null,name:'',active:false,targets:['workspace'],starts_at:'',ends_at:'',email:'',url:'',i18n:{et:{title:'',description:'',button:'Ava lisainfo'},en:{title:'',description:'',button:'Learn more'}}});
  const blankNotice=()=>({...blank(),active:true,popover:false,background:'#111827',text_color:'#ffffff',background_url:''});
  let settings={payments_paused:false,client_login_paused:false,message:'',...(data.maintenance_settings||{})};
  let screens=Array.isArray(data.info_screens)?data.info_screens:[];
  let notices=Array.isArray(data.notices)?data.notices:[];
  let selected=null,selectedNotice=null,saving=false,days=1,mail={subject:'',text:''},editorLanguage='et';
  const localDate=value=>value?new Date(value).toISOString().slice(0,16):'';
  const state=row=>!row.active?'Väljas':row.starts_at&&new Date(row.starts_at)>new Date()?'Planeeritud':row.ends_at&&new Date(row.ends_at)<new Date()?'Lõppenud':'Aktiivne';
  const edit=(row)=>selected=selected?.id===row.id?null:{...structuredClone(row),starts_at:localDate(row.starts_at),ends_at:localDate(row.ends_at)};
  const editNotice=(row)=>selectedNotice=selectedNotice?.id===row.id?null:{...structuredClone(row),starts_at:localDate(row.starts_at),ends_at:localDate(row.ends_at)};
  function touch(row){if(row===selectedNotice)selectedNotice=selectedNotice;if(row===selected)selected=selected;}
  function toggle(object,target){object.targets=object.targets.includes(target)?object.targets.filter(x=>x!==target):[...object.targets,target];touch(object);}
  function setFlag(row,key,event){row[key]=event.currentTarget.checked;touch(row);}
  const previewImage=row=>!row.popover&&/^https?:\/\//i.test(String(row.background_url||'').trim())?`url("${String(row.background_url).replace(/["\\]/g,'')}")`:'none';
  const languageLabel=code=>({et:'Eesti',en:'English',fi:'Suomi'}[code]||code.toUpperCase());
  function refreshEditor(row){queueMicrotask(()=>{if(row===selectedNotice)selectedNotice=selectedNotice;if(row===selected)selected=selected;});}
  async function call(body){saving=true;console.log('⚪','Saving');const response=await fetch('/@_api/admin/maintenance',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const result=await response.json().catch(()=>({}));saving=false;if(response.ok)console.log('🟢','Saved');else console.error('🔴',result.error||'Action failed');return {response,result};}
  const payload=row=>({...row,starts_at:row.starts_at?new Date(row.starts_at).toISOString():null,ends_at:row.ends_at?new Date(row.ends_at).toISOString():null});
  async function saveScreen(){if(!selected.targets.length)return console.warn('🟠','Vali vähemalt üks sihtkoht.');const current=selected;const {response,result}=await call({action:'save_screen',screen:payload(current)});if(response.ok){screens=current.id?screens.map(x=>x.id===current.id?result.screen:x):[result.screen,...screens];selected=null;document.getElementById('info_screen_create')?.hidePopover?.();}}
  async function saveNotice(){if(!selectedNotice.targets.length)return console.warn('🟠','Vali vähemalt üks sihtkoht.');const current=selectedNotice;const {response,result}=await call({action:'save_notice',notice:payload(current)});if(response.ok){notices=current.id?notices.map(x=>x.id===current.id?result.notice:x):[result.notice,...notices];selectedNotice=null;document.getElementById('notice_create')?.hidePopover?.();}}
  async function remove(kind,row){if(!row?.id||!confirm('Kustuta see kirje?'))return;const {response}=await call({action:kind==='screen'?'delete_screen':'delete_notice',id:row.id});if(response.ok){if(kind==='screen'){screens=screens.filter(x=>x.id!==row.id);selected=null;}else{notices=notices.filter(x=>x.id!==row.id);selectedNotice=null;}}}
  async function notifyTenants(){if(!mail.subject.trim()||!mail.text.trim())return console.warn('🟠','Lisa kirja teema ja sisu.');if(!confirm('Saada kiri kõigile aktiivse plaaniga tenantidele?'))return;const {response,result}=await call({action:'notify_tenants',...mail});if(response.ok){console.log('🟢',`Kiri saadeti ${result.sent} tenantile.`);mail={subject:'',text:''};document.getElementById('tenant_notify')?.hidePopover?.();}}
  async function saveSettings(){await call({action:'save',settings});}
  async function extendPlans(){if(confirm(`Lisa aktiivsetele Workspace plaanidele ${days} tasuta päeva?`))await call({action:'extend_plans',days});}
</script>

{#snippet targetsEditor(row)}
  <fieldset><legend>Sihtkohad</legend>
    <label class="check"><input type="checkbox" checked={row.targets.includes('extaas')} on:change={()=>toggle(row,'extaas')}> Extaas.com</label>
    <label class="check"><input type="checkbox" checked={row.targets.includes('workspace')} on:change={()=>toggle(row,'workspace')}> Workspace</label>
    <label class="check"><input type="checkbox" checked={row.targets.includes('tenant')} on:change={()=>toggle(row,'tenant')}> Tenant-portaalid (sh custom DNS)</label>
  </fieldset>
{/snippet}
{#snippet languagesEditor(row)}
  <section class="language-editor">
    <aside class="language-tabs" role="tablist" aria-label="Sisu keel">
      {#each Object.keys(row.i18n||{}) as code}
        <button type="button" role="tab" class="css _1 _transparent" class:active={editorLanguage===code} aria-selected={editorLanguage===code} aria-label={languageLabel(code)} title={languageLabel(code)} on:click={()=>editorLanguage=code}>
          <svg aria-hidden="true" viewBox="0 0 512 512">
            <use href={`/icons/flags.svg#${code}`}></use>
          </svg>
        </button>
        {/each}
      </aside><div class="language-fields grid gap _2" role="tabpanel"><header><small>{editorLanguage.toUpperCase()}</small><h4>{languageLabel(editorLanguage)}</h4></header><label>{editorLanguage==='et'?'Pealkiri':'Title'}<input bind:value={row.i18n[editorLanguage].title}></label><label>{editorLanguage==='et'?'Kirjeldus':'Description'}<textarea rows="6" bind:value={row.i18n[editorLanguage].description}></textarea></label>{#if row.url}<label>{editorLanguage==='et'?'Nupu tekst':'Button text'}<input bind:value={row.i18n[editorLanguage].button} placeholder={editorLanguage==='et'?'Ava lisainfo':'Learn more'}></label>{/if}</div></section>
{/snippet}
{#snippet noticePreview(row)}
  <details class="preview-details"><summary>Eelvaade</summary><section class:preview-popover={row.popover} class="notice-preview" style={`--preview-bg:${row.background};--preview-text:${row.text_color||'#fff'};--preview-image:${previewImage(row)}`}><small>{row.popover?'Popover':'Bänner'}</small><strong>{row.i18n[editorLanguage]?.title||'Teavituse pealkiri'}</strong><p>{row.i18n[editorLanguage]?.description||'Teavituse kirjeldus kuvatakse siin.'}</p>{#if row.url}<span>{row.i18n[editorLanguage]?.button||'Ava lisainfo'} →</span>{/if}</section></details>
{/snippet}
{#snippet commonEditor(row,notice=false)}
  <div class="editor-shell" on:input={()=>refreshEditor(row)}><div class="editor"><div class="facts"><label>Nimi<input bind:value={row.name}></label><label>Algus<input type="datetime-local" bind:value={row.starts_at}></label><label>Lõpp<input type="datetime-local" bind:value={row.ends_at}></label><label>URL<input type="url" bind:value={row.url} placeholder="https://…"></label>{#if !notice}<label>E-post<input type="email" bind:value={row.email}></label>{:else}<label>Taust<input type="color" bind:value={row.background}></label><label>Teksti värv<input type="color" bind:value={row.text_color}></label><label>Taustapildi URL<input type="url" bind:value={row.background_url} placeholder="https://…"></label><label class="check"><input type="checkbox" checked={row.popover} on:change={(event)=>setFlag(row,'popover',event)}> Kuva popover’ina</label>{/if}<label class="check"><input type="checkbox" checked={row.active} on:change={(event)=>setFlag(row,'active',event)}> Aktiivne</label>{@render targetsEditor(row)}</div>{@render languagesEditor(row)}</div>{#if notice}{@render noticePreview(row)}{/if}</div>
{/snippet}

<section class="maintenance grid gap _3">
  <header><small>Extaas platform</small><h2>Maintenance</h2><p>Extaas.com-i, Workspace’i ja tenant-portaalide teated ning teenuste ajutine juhtimine.</p></header>

  <section class="table-panel"><header class="flex _space _bottom gap _2 _wrap"><div><h3>Info screen sündmused</h3><small>Tenant-valik hõlmab nii /t/... kui ka custom DNS portaale.</small></div><nav class="flex gap _2"><button class="btn" popovertarget="tenant_notify">Teavita</button><button class="btn" popovertarget="maintenance_compensation">Kompensatsioon</button><button class="btn _color" popovertarget="info_screen_create" on:click={()=>selected=blank()}>Uus info screen</button></nav></header><div class="table-wrap"><table><thead><tr><th>Nimi</th><th>Sihtkoht</th><th>Algus</th><th>Lõpp</th><th>Olek</th></tr></thead><tbody>{#each screens as row}<tr class:open={selected?.id===row.id} on:click={()=>edit(row)}><td>{row.name||'Info screen'}</td><td>{row.targets.join(' + ')}</td><td>{row.starts_at?new Date(row.starts_at).toLocaleString('et-EE'):'Kohe'}</td><td>{row.ends_at?new Date(row.ends_at).toLocaleString('et-EE'):'Tähtajatu'}</td><td><span class="status">{state(row)}</span></td></tr>{#if selected?.id===row.id}<tr class="detail-row"><td colspan="5">{@render commonEditor(selected)}<footer class="flex _space"><button on:click|stopPropagation={()=>remove('screen',selected)}>Kustuta</button><button class="btn _color" on:click|stopPropagation={saveScreen}>Salvesta</button></footer></td></tr>{/if}{:else}<tr><td colspan="5">Kirjeid pole.</td></tr>{/each}</tbody></table></div></section>

  <section class="table-panel"><header class="flex _space _bottom"><div><h3>Teavitused</h3><small>Bänner või 7-päevase sulgemisküpsisega popover.</small></div><button class="btn _color" popovertarget="notice_create" on:click={()=>selectedNotice=blankNotice()}>Uus teavitus</button></header><div class="table-wrap"><table><thead><tr><th>Nimi</th><th>Sihtkoht</th><th>Esitus</th><th>Algus</th><th>Olek</th></tr></thead><tbody>{#each notices as row}<tr class:open={selectedNotice?.id===row.id} on:click={()=>editNotice(row)}><td>{row.name||'Teavitus'}</td><td>{row.targets.join(' + ')}</td><td>{row.popover?'Popover':'Bänner'}</td><td>{row.starts_at?new Date(row.starts_at).toLocaleString('et-EE'):'Kohe'}</td><td><span class="status">{state(row)}</span></td></tr>{#if selectedNotice?.id===row.id}<tr class="detail-row"><td colspan="5">{@render commonEditor(selectedNotice,true)}<footer class="flex _space"><button on:click|stopPropagation={()=>remove('notice',selectedNotice)}>Kustuta</button><button class="btn _color" on:click|stopPropagation={saveNotice}>Salvesta</button></footer></td></tr>{/if}{:else}<tr><td colspan="5">Teavitusi pole.</td></tr>{/each}</tbody></table></div></section>

  <article id="info_screen_create" popover class="create-popover panel"> <header class="flex _space"><h3>Uus info screen</h3><button popovertarget="info_screen_create" popovertargetaction="hide">×</button></header>{#if selected&&!selected.id}{@render commonEditor(selected)}<footer class="flex _end"><button class="btn _color" on:click={saveScreen}>Loo sündmus</button></footer>{/if}</article>
  <Popover id="notice_create" showLanguage={false} width={900}><section class="popover-form css _padding _radius grid gap _2"><header><h3>Uus teavitus</h3></header>{#if selectedNotice&&!selectedNotice.id}{@render commonEditor(selectedNotice,true)}<footer class="flex _end"><button class="btn _color" on:click={saveNotice}>Loo teavitus</button></footer>{/if}</section></Popover>
  <Popover id="tenant_notify" showLanguage={false} width={620}><section class="notify css _padding _radius"><header><h3>Teavita aktiivseid tenante</h3><small>Saajad leitakse aktiivsete Stripe plaanide järgi.</small></header><label>Teema<input maxlength="160" bind:value={mail.subject}></label><label>Sisu<textarea rows="10" bind:value={mail.text}></textarea></label><footer class="flex _end"><button class="btn _color" disabled={saving} on:click={notifyTenants}>Saada kiri</button></footer></section></Popover>
  <Popover id="maintenance_compensation" showLanguage={false} width={500}><section class="notify css _padding _radius"><header><h3>Kompenseeri hooldusaeg</h3><small>Ainult aktiivse plaaniga Workspace’i portaalid saavad lisaaega.</small></header><label>Päevade arv<input type="number" min="1" max="30" bind:value={days}></label><footer class="flex _end"><button class="btn _color" disabled={saving} on:click={extendPlans}>Lisa tasuta päevi</button></footer></section></Popover>

  <hr>
  <section class="panel services"><header><h3>Workspace teenuste olek</h3><small>Need lülitid kehtivad ainult workspace.extaas.com-le.</small></header><label class="check"><input type="checkbox" bind:checked={settings.client_login_paused}> Peata klientide privaatne ligipääs</label><label class="check"><input type="checkbox" bind:checked={settings.payments_paused}> Peata Extaas-poolsed maksed</label><label>Sisemine teade<textarea rows="3" bind:value={settings.message}></textarea></label><footer class="flex _end"><button on:click={saveSettings}>Salvesta teenuste olek</button></footer></section>
</section>

<style>
  .maintenance{width:min(1100px,100%);margin:auto}.maintenance :is(h2,h3,p,h4){margin:0}.panel,.table-panel{border:1px solid #222;border-radius:8px;background:#080808;overflow:hidden}.panel{padding:18px}.table-panel>header{padding:16px 18px;border-bottom:1px solid #222;background:#111}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:11px 13px;border-bottom:1px solid #222;text-align:left;white-space:nowrap}tbody>tr:not(.detail-row){cursor:pointer}.open{background:#16130c}.detail-row>td{padding:18px;white-space:normal}.editor{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,.8fr);gap:22px}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;align-content:start}.language-block,fieldset{border:1px solid #292929;border-radius:7px;padding:12px}.maintenance label{display:grid;gap:5px}.check{display:flex!important;align-items:center;gap:8px!important}.check input{width:auto}.maintenance :is(input,textarea){width:100%;box-sizing:border-box}fieldset{grid-column:1/-1;display:grid;gap:8px}.status{padding:4px 8px;border-radius:99px;background:#222}.detail-row footer,.create-popover footer,.popover-form footer{margin-top:16px}.services{display:grid;gap:12px}.notice-status{position:sticky;bottom:12px;padding:11px;border:1px solid #654;background:#211}.create-popover{position:fixed;inset:auto;margin:auto;width:min(900px,calc(100% - 30px));max-height:calc(100dvh - 30px);overflow:auto;color:#fff}.create-popover::backdrop{background:#000b;backdrop-filter:blur(4px)}.create-popover>header{margin-bottom:16px}.notify,.popover-form{display:grid;gap:14px}.popover-form .editor,.popover-form .facts{grid-template-columns:1fr}.maintenance>hr{width:100%;border:0;border-top:1px solid #222}@media(max-width:780px){.editor{grid-template-columns:1fr}.facts{grid-template-columns:1fr}}
  .preview-details{margin-top:14px}.preview-details summary{cursor:pointer;font-weight:800}.notice-preview{position:relative;isolation:isolate;overflow:hidden;display:grid;gap:5px;margin-top:10px;padding:14px 18px;border-radius:8px;background:var(--preview-bg);color:#fff}.notice-preview::before{content:"";position:absolute;z-index:-1;inset:0 0 0 auto;width:42%;background-image:linear-gradient(90deg,var(--preview-bg),transparent 45%),var(--preview-image);background-position:center;background-size:cover;opacity:.42}.notice-preview strong{font-size:16px}.notice-preview :is(p,small,span){color:#eee!important}.notice-preview.preview-popover{width:min(460px,100%);margin-inline:auto;padding:24px;border:1px solid #ffffff30;box-shadow:0 18px 50px #0008}
  .language-editor{display:grid;grid-template-columns:40px minmax(0,1fr);gap:10px;align-content:start}.language-tabs{display:grid;grid-template-columns:1fr;align-content:start;gap:8px;padding:0;border:0;background:transparent}.language-tabs button{display:grid;place-items:center;aspect-ratio:1;width:40px;border:1px solid transparent;border-radius:9px;background:transparent;color:#aaa;cursor:pointer}.language-tabs button:hover{background:#171717;color:#fff}.language-tabs svg{display:block;width:100%;height:100%;border-radius:4px;box-shadow:0 0 0 1px #ffffff20;overflow:hidden}.language-fields{padding:13px;border:1px solid #292929;border-radius:10px;background:#0b0b0b}.language-fields header{display:flex;align-items:baseline;gap:8px}.notice-preview,.notice-preview :is(strong,p,small,span){color:var(--preview-text)!important}@media(max-width:620px){.language-editor{grid-template-columns:1fr}.language-tabs{grid-template-columns:repeat(auto-fit,44px);overflow-x:auto}}
</style>
